<?php
require_once __DIR__.'/config/app.php'; $user=require_role(['admin']); $EMS_WITH_SIDEBAR=true;
require_once __DIR__.'/includes/layout.php'; page_header('Employees',$user); echo flash();

if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$gender=$_POST['gender']?:null;$phone=trim($_POST['phone']);$dept=trim($_POST['department']);$position=trim($_POST['position']);$address=trim($_POST['address']);if(isset($_POST['id'])&&$_POST['id']){$stmt=$pdo->prepare('UPDATE employees SET name=?,gender=?,phone=?,department=?,position=?,address=? WHERE id=?');$stmt->execute([$name,$gender,$phone,$dept,$position,$address,(int)$_POST['id']]);flash('Employee updated.');}else{$stmt=$pdo->prepare('INSERT INTO employees(name,gender,phone,department,position,address) VALUES(?,?,?,?,?,?)');$stmt->execute([$name,$gender,$phone,$dept,$position,$address]);flash('Employee added.');}}
if(isset($_GET['delete'])){verify_csrf();}
if(isset($_POST['delete_id'])){verify_csrf();$s=$pdo->prepare('DELETE FROM employees WHERE id=?');$s->execute([(int)$_POST['delete_id']]);flash('Employee deleted.');}
$rows=$pdo->query('SELECT * FROM employees ORDER BY name')->fetchAll();
?>
<button class="btn btn-primary mb-3" data-bs-toggle="modal" data-bs-target="#employeeModal">Add Employee</button>
<div class="modal" id="employeeModal"><div class="modal-dialog"><div class="modal-content"><form method="post"><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value=""><input class="form-control mb-2" name="name" placeholder="Name" required><select class="form-select mb-2" name="gender"><option value="">Gender</option><option value="male">Male</option><option value="female">Female</option><option value="other">Other</option></select><input class="form-control mb-2" name="phone" placeholder="Phone"><input class="form-control mb-2" name="department" placeholder="Department"><input class="form-control mb-2" name="position" placeholder="Position"><input class="form-control" name="address" placeholder="Address"></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div></div>
<div class="table-responsive"><table class="table table-striped"><thead><tr><th>Name</th><th>Phone</th><th>Department</th><th>Position</th><th>Action</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['phone'])?></td><td><?=htmlspecialchars($r['department'])?></td><td><?=htmlspecialchars($r['position'])?></td><td><form method="post" onsubmit="return confirm('Delete this employee?')"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><button class="btn btn-danger btn-sm" name="delete_id" value="<?=$r['id']?>">Delete</button></form></td></tr><?php endforeach?></tbody></table></div>
<?php page_footer(); ?>
